"""内置插件：管理（只读）。刻意只做只读查询：- 查看插件状态、命令总数- 查看自己的配额余量- 查看平台能力（决定插件该怎么降级）真正的管理动作（启停/重载插件）走 CLI：`haiqbot plugin reload <id>`。这样群里的管理员权限被攻破也无法动态加载代码。"""from __future__ import annotationsfrom haiqbot.plugin_api import Context, Plugin, Role, on_commandclass Admin(Plugin):    id = "admin"    name = "管理"    description = "只读的运行时状态查询"    capabilities: list[str] = []    @on_command("plugins", aliases=["插件"], usage="plugins", min_role=Role.ADMIN, priority=90)    async def list_plugins(self, ctx: Context) -> None:        if not ctx.introspect:            await ctx.reply.text("内省能力不可用")            return        rows = ctx.introspect.plugins()        lines = [f"🔌 插件 {len(rows)} 个"]        for row in rows:            marks = []            marks.append("✅" if row.get("loaded") else "⏸")            if not row.get("enabled"):                marks.append("(未启用)")            if row.get("error"):                marks.append("❌")            lines.append(f"  {''.join(marks)} {row['id']}  {row.get('version', '')}")        await ctx.reply.text("\n".join(lines))    @on_command("status", aliases=["状态"], usage="status", min_role=Role.ADMIN, priority=90)    async def status(self, ctx: Context) -> None:        caps = ctx.reply.capabilities        lines = [            "⚙️ 运行时状态",            f"  平台：{ctx.event.channel.platform if ctx.event else 'n/a'}",            f"  会话：{ctx.event.channel if ctx.event else 'n/a'}",            f"  图片：{'支持' if caps.image else '不支持'}（直发 URL：{'是' if caps.image_by_url else '否'}）",            f"  被动窗口：{'无限制' if caps.window_ttl is None else f'{caps.window_ttl:.0f}s'}",            f"  剩余：{_fmt_remaining(ctx)}",            f"  已加载插件：{len(ctx.introspect.plugins())}",        ]        await ctx.reply.text("\n".join(lines))def _fmt_remaining(ctx: Context) -> str:    rem = ctx.reply.remaining() if ctx.reply else None    if rem is None:        return "无限制"    return f"{max(0.0, rem):.0f}s"